package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

const (
	beaconIgnoreLine = ".beacon/"
	docsIgnoreLine   = "docs/beacon/"
)

// ensureArtifactsIgnored keeps the local `.beacon` workspace out of git:
// runtime state, artifacts, autotest and local evidence are machine-local.
// The root .gitignore is the reliable layer (the nested .gitignore alone
// would still show as an untracked directory before it is committed).
func ensureArtifactsIgnored(projRoot string) error {
	if err := ensureIgnoreLine(projRoot, beaconIgnoreLine,
		"# generated by beacon: local runtime state is not truth"); err != nil {
		return err
	}
	nested := filepath.Join(projRoot, ".beacon", "artifacts", ".gitignore")
	if err := os.MkdirAll(filepath.Dir(nested), 0o755); err != nil {
		return err
	}
	return os.WriteFile(nested, []byte("*\n!.gitignore\n"), 0o644)
}

// ensureDocsIgnored is the local-only mode: requirement documents stay on
// this machine, so colleagues never receive a half-adopted SDD workflow.
func ensureDocsIgnored(projRoot string) error {
	return ensureIgnoreLine(projRoot, docsIgnoreLine,
		"# generated by beacon --local-only: SDD docs are local")
}

func ensureIgnoreLine(projRoot, want, comment string) error {
	ignorePath := filepath.Join(projRoot, ".gitignore")
	raw, err := os.ReadFile(ignorePath)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	text := string(raw)
	if !hasIgnoreLine(text, want) {
		if text != "" && !strings.HasSuffix(text, "\n") {
			text += "\n"
		}
		text += "\n" + comment + "\n" + want + "\n"
		if err := os.WriteFile(ignorePath, []byte(text), 0o644); err != nil {
			return err
		}
	}
	return nil
}

func hasIgnoreLine(text, want string) bool {
	for _, line := range strings.Split(text, "\n") {
		switch strings.TrimSpace(line) {
		case want, strings.TrimSuffix(want, "/"), "/" + want:
			return true
		}
	}
	return false
}

func isInside(root, p string) bool {
	rel, err := filepath.Rel(root, p)
	return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// localOnlyMode reads the project-local switch. The file is intentionally
// under `.beacon/` (ignored), so the mode cannot leak into a colleague's
// checkout.
func localOnlyMode(projRoot string) bool {
	raw, err := os.ReadFile(filepath.Join(projRoot, ".beacon", "config"))
	if err != nil {
		return false
	}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			k, v, ok = strings.Cut(line, ":")
		}
		if ok && strings.TrimSpace(k) == "local_only" {
			return strings.EqualFold(strings.Trim(strings.TrimSpace(v), `"'`), "true")
		}
	}
	return false
}

func setLocalOnlyMode(projRoot string) error {
	config := filepath.Join(projRoot, ".beacon", "config")
	raw, err := os.ReadFile(config)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	text := string(raw)
	if localOnlyMode(projRoot) {
		return nil
	}
	if text != "" && !strings.HasSuffix(text, "\n") {
		text += "\n"
	}
	text += "local_only = true\n"
	if err := os.MkdirAll(filepath.Dir(config), 0o755); err != nil {
		return err
	}
	return os.WriteFile(config, []byte(text), 0o644)
}

// trackedDocs returns tracked docs/beacon paths; an empty slice means the
// caller may add the ignore rule without a cache-only removal step.
func trackedDocs(projRoot string) []string {
	cmd := exec.Command("git", "-C", projRoot, "ls-files", "docs/beacon")
	raw, err := cmd.Output()
	if err != nil {
		return nil
	}
	var out []string
	for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
		if line != "" {
			out = append(out, line)
		}
	}
	return out
}

func untrackCommand() string {
	return fmt.Sprintf("git rm -r --cached %s", strings.TrimSuffix(docsIgnoreLine, "/"))
}
